const slaces=[{id:'everyday',name:'Pocket Playground',subtitle:'Small games. Shared discoveries.',about:'Share playable games, creative tools, and interactive experiments. Try something together.',members:['Studio Small','Form & Play'],posts:['beat','draw'],color:'#f1e6d8',mark:'☺'},{id:'curiosity',name:'Curiosity Lab',subtitle:'Explore another possibility together.',about:'Share science experiments, simulations, and playable ideas. Turn a question into a Slice others can explore.',members:['Kepler Lab','Almost Physics','Little Worlds'],posts:['orbit','wave','city'],color:'#e4ead8',mark:'✳'}];
const membershipData=readStored('slice-slace-membership-v1',[]);let joinedSlaces=new Set(Array.isArray(membershipData)?membershipData.filter(id=>slaces.some(s=>s.id===id)):[]);let currentSlace='everyday';
const slacePage=document.createElement('main');slacePage.id='slace-page';slacePage.hidden=true;followingPage.after(slacePage);
function slaceCards(list){return list.map(w=>`<article class="card following-feed-card"><div class="following-byline"><span class="following-avatar">${escapeHtml(w.author.slice(0,1))}</span><div><strong>${escapeHtml(w.author)}</strong><small>Space member · ${escapeHtml(w.time)}</small></div></div><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.desc)}</p>${stage(w)}<div class="card-actions"><button data-like="${w.id}" aria-pressed="${likes.has(w.id)}">${likes.has(w.id)?'♥':'♡'} ${w.likes+(likes.has(w.id)?1:0)}</button><button data-share="${w.id}">↗ Share</button><button data-save="${w.id}" aria-pressed="${libraryIds.has(w.id)}">${libraryIds.has(w.id)?'✓ Saved':'＋ Library'}</button><button data-open="${w.id}">Play Slice ↗</button></div></article>`).join('')}
function renderSlace(){const s=slaces.find(x=>x.id===currentSlace),joined=joinedSlaces.has(s.id),list=works.filter(w=>w.slaceId===s.id||s.posts.includes(w.id));slacePage.innerHTML=`<div class="slace-heading"><div><span class="eyebrow">SPACES FOR SHARED CURIOSITY</span><h1>Space</h1><p>Shared spaces for creators and playable discoveries.</p></div><span class="slace-prototype">Community prototype · Saved locally</span></div><div class="slace-switch" role="group" aria-label="Choose a Space">${slaces.map(x=>`<button data-slace="${x.id}" aria-pressed="${x.id===s.id}">${x.mark} ${x.name}${joinedSlaces.has(x.id)?' · Joined':''}</button>`).join('')}</div><section class="slace-cover" style="background:${s.color}"><div class="slace-emblem">${s.mark}</div><div><span>SPACE / ${s.id.toUpperCase()}</span><h2>${s.name}</h2><p>${s.subtitle}</p><small>${s.members.length+(joined?1:0)} members · ${list.length} Slices</small></div><div class="slace-cover-actions"><button class="dark" data-slace-join>${joined?'Joined ✓ · Leave Space':'＋ Join Space'}</button><button data-slace-publish ${joined?'':'disabled'}>＋ Publish a Slice here</button></div></section><div class="following-feed-layout"><section class="following-stream"><div class="slace-stream-title"><h3>Experiences in this Space</h3><span>From members</span></div>${slaceCards(list)||'<div class="following-feed-empty">No experiences yet. Share the first playable discovery.</div>'}</section><aside class="following-feed-aside"><h3>About this Space</h3><p>${s.about}</p><h3>Members</h3>${s.members.map(a=>`<div class="followed-person"><span class="following-avatar">${escapeHtml(a.slice(0,1))}</span><span>${escapeHtml(a)} <small>Slicer</small></span></div>`).join('')}${joined?'<div class="followed-person"><span class="following-avatar">You</span><span>You <small>Joined</small></span></div>':''}<div class="slace-rules"><strong>Sharing here</strong><p>Join to publish interactive experiences that fit this Space. Respect fellow creators.</p></div><p class="following-local-note">Demo spaces and members. Memberships and new experiences stay in this browser. Multiplayer sync is not available yet.</p></aside></div>`;initStages(slacePage)}
function syncSlaceRoute(){const match=location.hash.match(/^#slace(?:\/([a-z]+))?$/);slacePage.hidden=!match;if(!match)return;if(match[1]&&slaces.some(s=>s.id===match[1]))currentSlace=match[1];document.querySelector('main#discover').hidden=true;followingPage.hidden=true;document.querySelectorAll('header nav a').forEach(a=>{a.classList.toggle('current',a.id==='slace-link');if(a.id==='slace-link')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});renderSlace()}
const slaceField=document.createElement('label');slaceField.className='slace-publish-field';slaceField.innerHTML='Publish to <select name="slaceDestination"><option value="">Personal Slice (outside a Space)</option></select><small>Join a Space to publish there. Your experience also appears in Discover.</small>';document.querySelector('.publish-fields').prepend(slaceField);
function updateSlaceOptions(value=''){publishForm.elements.slaceDestination.innerHTML='<option value="">Personal Slice (outside a Space)</option>'+slaces.filter(s=>joinedSlaces.has(s.id)).map(s=>`<option value="${s.id}">${s.name} · Space</option>`).join('');publishForm.elements.slaceDestination.value=joinedSlaces.has(value)?value:''}
const preSlaceCreator=openCreator;openCreator=function(work){preSlaceCreator(work);updateSlaceOptions((work||readStored(draftKey,null))?.slaceId||'')};
const preSlaceForm=formData;formData=function(){return {...preSlaceForm(),slaceId:publishForm.elements.slaceDestination.value}};
const preSlacePublish=publishForm.onsubmit;publishForm.onsubmit=e=>{const id=publishForm.elements.slaceDestination.value;if(id&&!joinedSlaces.has(id)){e.preventDefault();document.querySelector('#publish-error').textContent='Join this Space first.';return}preSlacePublish(e);if(!publishDialog.open&&id){currentSlace=id;location.hash='slace/'+id;renderSlace();window.scrollTo({top:0,behavior:'smooth'});toast('Published to '+slaces.find(s=>s.id===id).name+' · Saved locally')}};
slacePage.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.slace){location.hash='slace/'+b.dataset.slace}if(b.hasAttribute('data-slace-join')){const next=new Set(joinedSlaces);next.has(currentSlace)?next.delete(currentSlace):next.add(currentSlace);try{localStorage.setItem('slice-slace-membership-v1',JSON.stringify([...next]))}catch{toast('Could not save membership. Check browser storage.');return}joinedSlaces=next;renderSlace();updateSlaceOptions();toast(next.has(currentSlace)?'Joined the Space. You can now publish an experience here.':'Left the Space. Existing experiences are retained.')}if(b.hasAttribute('data-slace-publish')&&joinedSlaces.has(currentSlace)){openCreator();updateSlaceOptions(currentSlace)}});
const preSlaceRender=render;render=function(){preSlaceRender();if(!slacePage.hidden)renderSlace()};
window.addEventListener('hashchange',syncSlaceRoute);updateSlaceOptions();syncSlaceRoute();
